     2→import { registry, humanize } from "./route-registry";
     3→import type { RouteEntry } from "./route-compiler";
     4→import type { IconData } from "@/components/ui/icon-picker";
     5→import type { WorkspaceSection } from "./navigation-meta";
     6→
     7→// ─── Types ──────────────────────────────────────────────────────────────────
     8→
     9→export interface NavigateHeaders {
    10→  label?: string;
    11→  icon?: IconData;
    12→  id?: string;
    13→  sourceNodeId?: string;
    14→  parentNodeId?: string;
    15→  meta?: BreadcrumbMeta;
    16→}
    17→
    18→export interface BreadcrumbMeta {
    19→  workspaceId?: string;
    20→  section?: WorkspaceSection;
    21→  routePath?: string;
    22→  pageSlug?: string;
    23→  agentId?: string;
    24→  executorType?: string;
    25→  webId?: string;
    26→  url?: string;
    27→  blockId?: string;
    28→}
    29→
    30→export interface BreadcrumbStackItem {
    31→  id: string;
    32→  label: string;
    33→  titleKey?: string;
    34→  href: string;
    35→  icon?: IconData;
    36→  descriptorId?: string;
    37→  pattern?: string;
    38→  sourceNodeId?: string;
    39→  parentNodeId?: string;
    40→  meta?: BreadcrumbMeta;
    41→}
    42→
    43→// ─── Cold Start Builder ─────────────────────────────────────────────────────
    44→
    45→export function buildColdStartBreadcrumb(url: string, headers?: NavigateHeaders): BreadcrumbStackItem[] {
    46→  const match = registry.match(url);
    47→  if (!match) return [];
    48→
    49→  const chain: BreadcrumbStackItem[] = [];
    50→
    51→  // 1. Path prefix ancestors
    52→  for (const ancestorPattern of deriveAncestorsFromPrefix(match.pattern)) {
    53→    const ancestorEntry = registry.getEntry(ancestorPattern)!;
    54→    const ancestorParams = pickMatchingParams(ancestorPattern, match.params);
    55→    const item = buildBreadcrumbItem(ancestorEntry, ancestorParams);
    56→
    57→    // Annotate workspace root for buildDerivedHeader to detect
    58→    if (ancestorPattern === "/workspace/:workspaceId" && ancestorParams.workspaceId) {
    59→      item.descriptorId = "workspace";
    60→      item.meta = { ...item.meta, workspaceId: ancestorParams.workspaceId };
    61→    }
    62→
    63→    chain.push(item);
    64→  }
    65→
    66→  // 2. Rest param intermediate levels
    67→  const restParam = registry.getRestParam(match.pattern);
    68→  if (restParam && match.params[restParam]?.includes("/")) {
    69→    const segments = match.params[restParam].split("/");
    70→    for (let i = 1; i < segments.length; i++) {
    71→      const prefix = segments.slice(0, i).join("/");
    72→      const lastSegment = segments[i - 1];
    73→      chain.push(buildBreadcrumbItem(
    74→        match.entry,
    75→        { ...match.params, [restParam]: prefix },
    76→        { label: humanize(lastSegment) },
    77→      ));
    78→    }
    79→  }
    80→
    81→  // 3. Current node (headers can override label/icon)
    82→  const currentItem = buildBreadcrumbItem(match.entry, match.params, headers);
    83→
    84→  // Annotate workspace root when it is the leaf (direct navigation to workspace home)
    85→  if (match.pattern === "/workspace/:workspaceId" && match.params.workspaceId) {
    86→    currentItem.descriptorId = currentItem.descriptorId ?? "workspace";
    87→    currentItem.meta = { ...currentItem.meta, workspaceId: match.params.workspaceId };
    88→  }
    89→
    90→  chain.push(currentItem);
    91→
    92→  return chain;
    93→}
    94→
    95→// ─── Helpers ────────────────────────────────────────────────────────────────
    96→
    97→export function deriveAncestorsFromPrefix(pattern: string): string[] {
    98→  const segments = pattern.split("/").filter(Boolean);
    99→  const ancestors: string[] = [];
   100→
   101→  for (let i = segments.length - 1; i > 0; i--) {
   102→    const candidate = "/" + segments.slice(0, i).join("/");
   103→    const entry = registry.getEntry(candidate);
   104→    if (entry && !entry.isContainer) {
   105→      ancestors.unshift(candidate);
   106→    }
   107→  }
   108→  return ancestors;
   109→}
   110→
   111→export function pickMatchingParams(
   112→  targetPattern: string,
   113→  allParams: Record<string, string>,
   114→): Record<string, string> {
   115→  const paramNames = registry.getParamNames(targetPattern);
   116→  const result: Record<string, string> = {};
   117→  for (const name of paramNames) {
   118→    if (allParams[name] !== undefined) {
   119→      result[name] = allParams[name];
   120→    }
   121→  }
   122→  return result;
   123→}
   124→
   125→export function buildBreadcrumbItem(
   126→  entry: RouteEntry,
   127→  params: Record<string, string>,
   128→  headers?: NavigateHeaders,
   129→): BreadcrumbStackItem {
   130→  const href = registry.build(entry.pattern, params);
   131→  const icon = headers?.icon ?? (typeof entry.icon === "function" ? entry.icon(params) : entry.icon);
   132→  const title = typeof entry.title === "function" ? entry.title(params) : entry.title;
   133→
   134→  return {
   135→    id: headers?.id ?? href,
   136→    label: headers?.label ?? title,
   137→    titleKey: entry.titleKey,
   138→    icon,
   139→    pattern: entry.pattern,
   140→    href,
   141→    sourceNodeId: headers?.sourceNodeId,
   142→    parentNodeId: headers?.parentNodeId,
   143→    meta: headers?.meta,
   144→  };
   145→}
