   113→export function stackToDesktopSegments(
   114→  stack: BreadcrumbStackItem[] | undefined
   115→): DesktopBreadcrumbSegment[] {
   116→  if (!stack || stack.length <= 1) {
   117→    return [];
   118→  }
   119→
   120→  return stack.slice(1).map((item) => ({
   121→    id: item.id,
   122→    label: item.label,
   123→    href: item.href,
   124→    icon: item.icon,
   125→    descriptorId: item.descriptorId,
   126→    meta: item.meta,
   127→  }));
   128→}
   129→
   130→export function buildFallbackDesktopSegment(input: {
   131→  id: string;
   132→  label: string;
   133→  href: string;
   134→  descriptorId: string;
   135→  icon?: IconData;
   136→  meta?: DesktopBreadcrumbSegment["meta"];
   137→}): DesktopBreadcrumbSegment {
   138→  const item = createBreadcrumbItem({
   139→    id: input.id,
   140→    label: input.label,
   141→    href: input.href,
   142→    descriptorId: input.descriptorId,
   143→    icon: input.icon,
   144→    meta: input.meta,
   145→  });
   146→
   147→  return {
   148→    id: item.id,
   149→    label: item.label,
   150→    href: item.href,
   151→    icon: item.icon,
   152→    descriptorId: item.descriptorId,
   153→    meta: item.meta,
   154→  };
   155→}
   156→
   157→export function buildWorkspaceSectionHeaderSegment(
   158→  workspaceId: string,
   159→  section: WorkspaceSection,
   160→  buildLabel?: (titleKey: string, fallbackLabel: string) => string
   161→): DesktopBreadcrumbSegment {
   162→  const info = getWorkspaceSectionDescriptor(section);
   163→  const routePath = section;
   164→
   165→  return {
   166→    id: `workspace:${workspaceId}:${section}`,
   167→    label: info
   168→      ? buildLabel?.(info.titleKey, info.fallbackLabel) ??
   169→        info.fallbackLabel
   170→      : section,
   171→    href: `/workspace/${encodeURIComponent(workspaceId)}/${routePath}`,
   172→    icon: info?.icon,
   173→    descriptorId: `workspace-section:${section}`,
   174→    meta: {
   175→      workspaceId,
   176→      section,
   177→      routePath,
   178→    },
   179→  };
   180→}
   181→
   182→export function resolveHeaderSegments(input: {
   183→  stack?: BreadcrumbStackItem[];
   184→  fallback?: DesktopBreadcrumbSegment[];
   185→  patchLast?: Partial<DesktopBreadcrumbSegment> & {
   186→    meta?: DesktopBreadcrumbSegment["meta"];
   187→  };
   188→}): DesktopBreadcrumbSegment[] {
   189→  const stackSegments = stackToDesktopSegments(input.stack);
   190→  const patchLast = input.patchLast;
   191→
   192→  if (stackSegments.length === 0) {
   193→    return input.fallback ?? [];
   194→  }
   195→
   196→  if (!patchLast) {
   197→    return stackSegments;
   198→  }
   199→
   200→  return stackSegments.map((segment, index, segments) =>
   201→    index === segments.length - 1
   202→      ? {
   203→          ...segment,
   204→          ...patchLast,
   205→          meta: {
   206→            ...segment.meta,
   207→            ...patchLast.meta,
   208→          },
   209→        }
   210→      : segment
   211→  );
   212→}
   213→
   214→export function createWorkspaceRootNode(
   215→  workspaceId: string,
   216→  label = "Workspace"
   217→): VirtualPageIndexNode {
   218→  return {
   219→    id: `workspace:${workspaceId}`,
   220→    descriptorId: "workspace",
   221→    label,
   222→    icon: { type: "lucide", value: "folder-open" },
   223→    order: 0,
   224→    isContainer: true,
   225→  };
   226→}
   227→
   228→export function createStaticWorkspaceIndexNodes(
   229→  workspaceId: string
   230→): VirtualPageIndexNode[] {
   231→  const root = createWorkspaceRootNode(workspaceId);
   232→  const sectionNodes = WORKSPACE_SECTIONS.map((info, index) => ({
   233→    id: `${root.id}:${info.section}`,
   234→    descriptorId: `workspace-section:${info.section}`,
   235→    label: info.fallbackLabel,
   236→    icon: info.icon,
   237→    parentId: root.id,
   238→    order: index + 1,
   239→    href: `/workspace/${encodeURIComponent(workspaceId)}/${info.section}`,
   240→  }));
   241→
   242→  return [root, ...sectionNodes];
   243→}
   244→
   245→export function resolveSegmentDescriptorId(
   246→  segment: DesktopBreadcrumbSegment
   247→): string | undefined {
   248→  if (segment.descriptorId) {
   249→    return segment.descriptorId;
   250→  }
   251→
   252→  if (/^\/workspace\/[^/]+$/.test(segment.href)) {
   253→    return "workspace";
   254→  }
   255→
   256→  const sectionMatch = segment.href.match(
   257→    /^\/workspace\/[^/]+\/(chat|kanban|cron|ideas|pages|files|github|chat-monitor)$/
   258→  );
   259→  if (sectionMatch) {
   260→    return `workspace-section:${sectionMatch[1]}`;
   261→  }
   262→
   263→  if (/^\/workspace\/[^/]+\/(agent|agents)$/.test(segment.href)) {
   264→    return "workspace-section:agent";
   265→  }
   266→
   267→  if (/^\/agent\/[^/]+/.test(segment.href)) {
   268→    return "workspace-agent";
   269→  }
   270→
   271→  if (/^\/executor\/[^/]+/.test(segment.href)) {
   272→    return "workspace-executor";
   273→  }
   274→
   275→  const pageMatch = segment.href.match(/^\/workspace\/[^/]+\/pages\/(.+)$/);
   276→  if (pageMatch) {
   277→    return "workspace-page";
   278→  }
   279→
   280→  if (segment.href === "/settings") {
   281→    return "settings";
   282→  }
   283→
   284→  if (/^\/settings\/[^/]+/.test(segment.href)) {
   285→    return `settings:${segment.href.split("/settings/")[1]}`;
   286→  }
   287→
   288→  return undefined;
   289→}
