   291→export function buildRootDropdownItems({
   292→  workspaces = [],
   293→  currentArea = "home",
   294→  activeWorkspaceId,
   295→  currentSection,
   296→  activeHref,
   297→  buildLabel,
   298→  onSelectWorkspace,
   299→  labelGlobalWorkspace,
   300→}: {
   301→  workspaces?: WorkspaceListItemLike[];
   302→  currentArea?: "home" | "pages" | "section";
   303→  activeWorkspaceId?: string;
   304→  currentSection?: WorkspaceSection;
   305→  activeHref?: string;
   306→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
   307→  onSelectWorkspace?: (workspaceId: string) => void;
   308→  labelGlobalWorkspace?: string;
   309→}): BreadcrumbDropdownItem[] {
   310→  const sectionRoutePath = currentSection
   311→    ? getWorkspaceSectionRoutePath(currentSection)
   312→    : "";
   313→
   314→  const workspaceItems = buildDropdownItems(workspaces, (workspace) => {
   315→    const workspaceLabel =
   316→      workspace.type === "global"
   317→        ? labelGlobalWorkspace ??
   318→          buildLabel?.("workspace.global", "Global Workspace") ??
   319→          "Global Workspace"
   320→        : workspace.name;
   321→    const href =
   322→      currentArea === "pages"
   323→        ? `/workspace/${encodeURIComponent(workspace.id)}/pages`
   324→        : sectionRoutePath
   325→          ? `/workspace/${encodeURIComponent(workspace.id)}/${sectionRoutePath}`
   326→          : `/workspace/${encodeURIComponent(workspace.id)}`;
   327→
   328→    return {
   329→      id: `workspace:${workspace.id}`,
   330→      label: workspaceLabel,
   331→      href,
   332→      description: workspace.path,
   333→      icon: {
   334→        type: "lucide",
   335→        value: workspace.type === "global" ? "globe" : "folder-open",
   336→      } as IconData,
   337→      isActive: workspace.id === activeWorkspaceId,
   338→      descriptorId: "workspace",
   339→      meta: {
   340→        workspaceId: workspace.id,
   341→        section: currentSection,
   342→        routePath: sectionRoutePath || undefined,
   343→      },
   344→      onSelect: onSelectWorkspace
   345→        ? () => onSelectWorkspace(workspace.id)
   346→        : undefined,
   347→    };
   348→  });
   349→
   350→  const systemItems = buildDropdownItems(
   351→    [
   352→      {
   353→        id: "root:settings",
   354→        label: getSettingsSectionLabel(),
   355→        href: "/settings/general",
   356→        icon: getSettingsSectionIcon(),
   357→        isActive: activeHref?.startsWith("/settings") ?? false,
   358→      },
   359→      {
   360→        id: "root:documents",
   361→        label: buildLabel?.("nav.documents", "Documents") ?? "Documents",
   362→        href: "/documents",
   363→        icon: { type: "lucide", value: "file-text" } as IconData,
   364→        isActive: activeHref === "/documents",
   365→      },
   366→      {
   367→        id: "root:devices",
   368→        label: buildLabel?.("nav.devices", "Devices") ?? "Devices",
   369→        href: "/devices/pair",
   370→        icon: { type: "lucide", value: "smartphone" } as IconData,
   371→        isActive: activeHref === "/devices/pair",
   372→      },
   373→    ],
   374→    (item) => ({
   375→      ...item,
   376→      descriptorId: item.id.replace("root:", ""),
   377→    })
   378→  );
   379→
   380→  return [...workspaceItems, ...systemItems];
   381→}
   382→
   383→function buildWorkspaceSectionMenuDropdownItems({
   384→  workspaceId,
   385→  activeSection,
   386→  buildLabel,
   387→  onSelectSection,
   388→  allowGithub = true,
   389→}: {
   390→  workspaceId: string;
   391→  activeSection?: WorkspaceSection;
   392→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
   393→  onSelectSection?: (
   394→    section: WorkspaceSection,
   395→    routePath: string,
   396→    href: string
   397→  ) => void;
   398→  allowGithub?: boolean;
   399→}): BreadcrumbDropdownItem[] {
   400→  return buildDropdownItems(
   401→    WORKSPACE_SECTIONS.filter((item) =>
   402→      allowGithub ? true : item.section !== "github"
   403→    ),
   404→    (item) => {
   405→      const routePath = item.section;
   406→      const href = `/workspace/${encodeURIComponent(workspaceId)}/${routePath}`;
   407→      return {
   408→        id: `workspace:${workspaceId}:${item.section}`,
   409→        label:
   410→          buildLabel?.(item.titleKey, item.fallbackLabel) ?? item.fallbackLabel,
   411→        href,
   412→        icon: item.icon,
   413→        isActive: item.section === activeSection,
   414→        descriptorId: `workspace-section:${item.section}`,
   415→        meta: {
   416→          workspaceId,
   417→          section: item.section,
   418→          routePath,
   419→        },
   420→        onSelect: onSelectSection
   421→          ? () => onSelectSection(item.section, routePath, href)
   422→          : undefined,
   423→      };
   424→    }
   425→  );
   426→}
