   472→export function buildWorkspacePagesDropdownItems({
   473→  workspaceId,
   474→  activeSection,
   475→  buildLabel,
   476→  onSelectSection,
   477→  allowGithub = true,
   478→  pages = [],
   479→  currentPageSlug,
   480→}: WorkspaceSectionDropdownInput & {
   481→  pages?: PageConfig[];
   482→  currentPageSlug?: string;
   483→}): BreadcrumbDropdownItem[] {
   484→  const sectionItems = buildWorkspaceSectionMenuDropdownItems({
   485→    workspaceId,
   486→    activeSection,
   487→    buildLabel,
   488→    onSelectSection,
   489→    allowGithub,
   490→  });
   491→  const pageItems = buildDropdownItems(
   492→    pages.filter((page) => !page.slug.includes("/")),
   493→    (page) => ({
   494→      id: `workspace:${workspaceId}:page:${page.slug}`,
   495→      label: page.name,
   496→      href: `/workspace/${encodeURIComponent(workspaceId)}/page/${page.slug
   497→        .split("/")
   498→        .filter(Boolean)
   499→        .map((segment) => encodeURIComponent(segment))
   500→        .join("/")}`,
   501→      icon: page.icon,
   502→      isActive:
