   739→            workspaceId: wId,
   740→            activeSection: section,
   741→            buildLabel: input.buildLabel,
   742→            onSelectSection: input.onSelectSection,
   743→            allowGithub: input.allowGithub,
   744→            pages: input.pages,
   745→            currentPageSlug: input.currentPageSlug,
   746→          });
   747→        }
