   749→        return buildWorkspaceSectionDropdownItems(section, {
   750→          workspaceId: wId,
   751→          activeSection: section,
   752→          buildLabel: input.buildLabel,
   753→          onSelectSection: input.onSelectSection,
   754→          allowGithub: input.allowGithub,
   755→        });
   756→      },
   757→    },
   758→    {
   759→      matches: (input, descriptorId) =>
   760→        descriptorId === "workspace-page" &&
   761→        Boolean(input.pages?.length),
   762→      build: (input) => {
   763→        const wId = input.workspaceId ?? input.segment.meta?.workspaceId ?? "";
