   446→      },
   447→
   448→      replaceLocation: (tabId, next) => {
   449→        set((state) => ({
   450→          tabs: state.tabs.map((tab) => {
   451→            if (tab.id !== tabId) return tab;
   452→            const current = normalizeTab(tab);
   453→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex);
   454→            return normalizeTab({
   455→              ...current,
   456→              navigationHistory: [...baseHistory, next],
   457→              historyIndex: baseHistory.length,
   458→            });
   459→          }),
   460→        }));
   461→      },
   462→
   463→      pushLocation: (tabId, next) => {
   464→        set((state) => ({
   465→          tabs: state.tabs.map((tab) => {
   466→            if (tab.id !== tabId) return tab;
   467→            const current = normalizeTab(tab);
   468→            let history = [...current.navigationHistory.slice(0, current.historyIndex + 1), next];
   469→            let index = history.length - 1;
   470→            // Trim oldest entries if history exceeds limit
   471→            if (history.length > MAX_NAVIGATION_HISTORY) {
   472→              const excess = history.length - MAX_NAVIGATION_HISTORY;
   473→              history = history.slice(excess);
   474→              index = history.length - 1;
   475→            }
   476→            return normalizeTab({
   477→              ...current,
   478→              navigationHistory: history,
   479→              historyIndex: index,
   480→            });
   481→          }),
   482→        }));
   483→      },
   484→
   485→      insertHistoryBeforeCurrent: (tabId, next) => {
   486→        set((state) => ({
   487→          tabs: state.tabs.map((tab) => {
   488→            if (tab.id !== tabId) return tab;
   489→            const current = normalizeTab(tab);
   490→            const before = current.navigationHistory.slice(0, current.historyIndex);
   491→            const fromCurrent = current.navigationHistory.slice(current.historyIndex);
   492→            return normalizeTab({
   493→              ...current,
   494→              navigationHistory: [...before, next, ...fromCurrent],
   495→              historyIndex: before.length,
   496→            });
   497→          }),
   498→        }));
   499→      },
   500→
   501→      jumpToHistory: (tabId, historyIndex) => {
   502→        set((state) => ({
   503→          tabs: state.tabs.map((tab) => {
   504→            if (tab.id !== tabId) return tab;
   505→            const current = normalizeTab(tab);
   506→            return normalizeTab({
   507→              ...current,
   508→              historyIndex,
   509→            });
   510→          }),
   511→        }));
   512→      },
   513→
   514→      goBack: (tabId) => {
   515→        set((state) => ({
   516→          tabs: state.tabs.map((tab) => {
   517→            if (tab.id !== tabId) return tab;
   518→            const current = normalizeTab(tab);
   519→            if (current.historyIndex <= 0) return current;
   520→            return {
   521→              ...current,
   522→              historyIndex: current.historyIndex - 1,
   523→            };
   524→          }),
   525→        }));
   526→      },
   527→
   528→      goForward: (tabId) => {
   529→        set((state) => ({
   530→          tabs: state.tabs.map((tab) => {
   531→            if (tab.id !== tabId) return tab;
   532→            const current = normalizeTab(tab);
   533→            if (current.historyIndex >= current.navigationHistory.length - 1) {
   534→              return current;
   535→            }
   536→            return {
   537→              ...current,
   538→              historyIndex: current.historyIndex + 1,
   539→            };
   540→          }),
   541→        }));
   542→      },
   543→
   544→      canGoBack: (tabId) => {
   545→        const tab = get().tabs.find((item) => item.id === tabId);
   546→        return tab ? normalizeTab(tab).historyIndex > 0 : false;
   547→      },
   548→
   549→      canGoForward: (tabId) => {
   550→        const tab = get().tabs.find((item) => item.id === tabId);
   551→        if (!tab) return false;
   552→        const current = normalizeTab(tab);
   553→        return current.historyIndex < current.navigationHistory.length - 1;
   554→      },
   555→
   556→      getCurrentUrl: (tabId) => {
   557→        const tab = get().tabs.find((item) => item.id === tabId);
