    10→import { DesktopBreadcrumbBar } from "./desktop-breadcrumb-bar";
    11→import { useActiveTabState } from "@/hooks/use-page-tabs";
    12→import { useLocalWorkspaces } from "@/hooks/use-workspaces";
    13→import type { DesktopBreadcrumbSegment } from "@/navigation/page-index";
    14→import type { BreadcrumbStackItem } from "@/navigation/breadcrumb-builder";
    15→import type { Workspace } from "@/types";
    16→
    17→interface NavigationShellHeaderState {
    18→  workspace?: Workspace;
    19→  segments?: DesktopBreadcrumbSegment[];
    20→  className?: string;
    21→}
    22→
    23→interface RegisteredNavigationShellHeader extends NavigationShellHeaderState {
    24→  ownerId: string;
    25→}
    26→
    27→interface NavigationShellActionsContextValue {
    28→  setHeader: (ownerId: string, next: NavigationShellHeaderState) => void;
    29→  clearHeader: (ownerId: string) => void;
    30→  setCenterContent: (ownerId: string, content: ReactNode | null) => void;
    31→  setRightContent: (ownerId: string, content: ReactNode | null) => void;
    32→  clearSlotContent: (ownerId: string) => void;
    33→}
    34→
    35→interface NavigationShellSlotsContextValue {
    36→  centerHost: HTMLDivElement | null;
    37→  rightHost: HTMLDivElement | null;
    38→  setCenterHost: (node: HTMLDivElement | null) => void;
    39→  setRightHost: (node: HTMLDivElement | null) => void;
    40→  centerContent: ReactNode | null;
    41→  rightContent: ReactNode | null;
    42→}
    43→
    44→const NavigationShellHeaderContext =
    45→  createContext<RegisteredNavigationShellHeader | null>(null);
    46→const NavigationShellActionsContext =
    47→  createContext<NavigationShellActionsContextValue | null>(null);
    48→const NavigationShellSlotsContext =
    49→  createContext<NavigationShellSlotsContextValue | null>(null);
    50→
    51→const EMPTY_SEGMENTS: DesktopBreadcrumbSegment[] = [];
    52→
    53→function areHeadersEqual(
    54→  current: RegisteredNavigationShellHeader | null,
    55→  ownerId: string,
    56→  next: NavigationShellHeaderState
    57→): boolean {
    58→  const currentWorkspaceId = current?.workspace?.id;
    59→  const nextWorkspaceId = next.workspace?.id;
    60→  const currentSegments = JSON.stringify(current?.segments ?? []);
    61→  const nextSegments = JSON.stringify(next.segments ?? []);
    62→
    63→  return (
    64→    current?.ownerId === ownerId &&
    65→    currentWorkspaceId === nextWorkspaceId &&
    66→    currentSegments === nextSegments &&
    67→    current.className === next.className
    68→  );
    69→}
    70→
    71→function mapStackItemToSegment(
    72→  item: BreadcrumbStackItem
    73→): DesktopBreadcrumbSegment {
    74→  return {
    75→    id: item.id,
    76→    label: item.label,
    77→    titleKey: item.titleKey,
    78→    href: item.href,
    79→    icon: item.icon,
    80→    descriptorId: item.descriptorId,
    81→    meta: item.meta,
    82→  };
    83→}
    84→
    85→function buildDerivedHeader(
    86→  stack: BreadcrumbStackItem[] | undefined,
    87→  workspaces: Workspace[]
    88→): NavigationShellHeaderState | null {
    89→  if (!stack?.length) {
    90→    return null;
    91→  }
    92→
    93→  const [root, ...rest] = stack;
    94→  if (root.descriptorId === "workspace" && root.meta?.workspaceId) {
    95→    const workspace = workspaces.find(
    96→      (item) => item.id === root.meta?.workspaceId
    97→    );
    98→
    99→    if (workspace) {
   100→      return {
   101→        workspace,
   102→        segments: rest.map(mapStackItemToSegment),
   103→      };
   104→    }
   105→  }
   106→
   107→  return {
   108→    segments: stack.map(mapStackItemToSegment),
   109→  };
   110→}
   111→
   112→export function resolveNavigationShellHeader(
   113→  registeredHeader: RegisteredNavigationShellHeader | null,
   114→  derivedHeader: NavigationShellHeaderState | null
   115→): NavigationShellHeaderState | null {
   116→  if (derivedHeader) {
   117→    return {
   118→      workspace: derivedHeader.workspace,
   119→      segments: derivedHeader.segments ?? EMPTY_SEGMENTS,
   120→      className: registeredHeader?.className,
   121→    };
   122→  }
   123→
   124→  if (!registeredHeader) {
   125→    return null;
   126→  }
   127→
   128→  return {
   129→    workspace: registeredHeader.workspace,
   130→    segments: registeredHeader.segments ?? EMPTY_SEGMENTS,
   131→    className: registeredHeader.className,
   132→  };
   133→}
   134→
   135→export function NavigationShellProvider({
   136→  children,
   137→}: {
   138→  children: ReactNode;
   139→}) {
   140→  const [header, setHeaderState] =
   141→    useState<RegisteredNavigationShellHeader | null>(null);
   142→  const [centerContent, setCenterContentState] = useState<ReactNode | null>(null);
   143→  const [rightContent, setRightContentState] = useState<ReactNode | null>(null);
   144→  const [centerHost, setCenterHost] = useState<HTMLDivElement | null>(null);
   145→  const [rightHost, setRightHost] = useState<HTMLDivElement | null>(null);
   146→  const slotOwnerRef = useRef<string | null>(null);
   147→
   148→  const setHeader = useCallback(
   149→    (ownerId: string, next: NavigationShellHeaderState) => {
   150→      setHeaderState((current) => {
   151→        if (areHeadersEqual(current, ownerId, next)) {
   152→          return current;
   153→        }
   154→
   155→        return {
   156→          ownerId,
   157→          ...next,
   158→        };
   159→      });
   160→    },
   161→    []
   162→  );
   163→
   164→  const clearHeader = useCallback((ownerId: string) => {
   165→    setHeaderState((current) =>
   166→      current?.ownerId === ownerId ? null : current
   167→    );
   168→  }, []);
   169→
   170→  const setCenterContent = useCallback((ownerId: string, content: ReactNode | null) => {
   171→    slotOwnerRef.current = ownerId;
   172→    setCenterContentState(content);
   173→  }, []);
   174→
   175→  const setRightContent = useCallback((ownerId: string, content: ReactNode | null) => {
   176→    slotOwnerRef.current = ownerId;
   177→    setRightContentState(content);
   178→  }, []);
   179→
   180→  const clearSlotContent = useCallback((ownerId: string) => {
   181→    if (slotOwnerRef.current !== ownerId) {
   182→      return;
   183→    }
   184→
   185→    slotOwnerRef.current = null;
   186→    setCenterContentState(null);
   187→    setRightContentState(null);
   188→  }, []);
   189→
   190→  const actionsValue = useMemo(
   191→    () => ({
   192→      setHeader,
   193→      clearHeader,
   194→      setCenterContent,
   195→      setRightContent,
   196→      clearSlotContent,
   197→    }),
   198→    [clearHeader, clearSlotContent, setCenterContent, setHeader, setRightContent]
   199→  );
   200→  const slotsValue = useMemo(
   201→    () => ({
   202→      centerHost,
   203→      rightHost,
   204→      setCenterHost,
   205→      setRightHost,
   206→      centerContent,
   207→      rightContent,
   208→    }),
   209→    [centerContent, centerHost, rightContent, rightHost]
   210→  );
   211→
   212→  return (
   213→    <NavigationShellActionsContext.Provider value={actionsValue}>
   214→      <NavigationShellSlotsContext.Provider value={slotsValue}>
   215→        <NavigationShellHeaderContext.Provider value={header}>
   216→          {children}
   217→        </NavigationShellHeaderContext.Provider>
   218→      </NavigationShellSlotsContext.Provider>
   219→    </NavigationShellActionsContext.Provider>
   220→  );
   221→}
   222→
   223→export function useOptionalNavigationShell() {
   224→  return useContext(NavigationShellActionsContext);
   225→}
   226→
   227→export function useNavigationShellHeaderState() {
   228→  return useContext(NavigationShellHeaderContext);
   229→}
   230→
   231→export function useNavigationShellSlots() {
   232→  return useContext(NavigationShellSlotsContext);
   233→}
   234→
   235→export function GlobalBreadcrumbShell() {
   236→  const registeredHeader = useContext(NavigationShellHeaderContext);
   237→  const slots = useContext(NavigationShellSlotsContext);
   238→  const { currentNavigationState } = useActiveTabState();
   239→  const { workspaces } = useLocalWorkspaces();
   240→
   241→  const derivedHeader = useMemo(
   242→    () => buildDerivedHeader(currentNavigationState?.breadcrumbStack, workspaces),
   243→    [currentNavigationState?.breadcrumbStack, workspaces]
   244→  );
   245→
   246→  const resolvedHeader = useMemo(() => {
   247→    return resolveNavigationShellHeader(registeredHeader, derivedHeader);
   248→  }, [derivedHeader, registeredHeader]);
   249→
   250→  const handleCenterHostRef = useCallback(
   251→    (node: HTMLDivElement | null) => {
   252→      slots?.setCenterHost(node);
   253→    },
   254→    [slots]
   255→  );
   256→
   257→  const handleRightHostRef = useCallback(
   258→    (node: HTMLDivElement | null) => {
   259→      slots?.setRightHost(node);
   260→    },
   261→    [slots]
   262→  );
   263→
   264→  if (!resolvedHeader) {
   265→    return null;
   266→  }
   267→
   268→  return (
   269→    <DesktopBreadcrumbBar
   270→      workspace={resolvedHeader.workspace}
   271→      segments={resolvedHeader.segments}
   272→      className={resolvedHeader.className}
   273→      centerSlot={
   274→        <div
   275→          ref={handleCenterHostRef}
   276→          className="flex min-w-0 items-center justify-center"
   277→        >
   278→          {slots?.centerContent}
   279→        </div>
   280→      }
   281→      rightSlot={
   282→        <div
   283→          ref={handleRightHostRef}
   284→          className="flex items-center gap-2"
   285→        >
   286→          {slots?.rightContent}
   287→        </div>
   288→      }
   289→    />
   290→  );
   291→}
