     1→import i18n from "@/i18n";
     2→import type { PageConfig } from "@/hooks/use-pages";
     3→import type { PageTreeNode } from "./page-tree";
     4→import {
     5→  resolveNavigationState,
     6→  type BreadcrumbNodeDescriptor,
     7→} from "@/navigation/navigation-state";
     8→
     9→function createWorkspacePagesIndexDescriptor(
    10→  workspaceId: string
    11→): BreadcrumbNodeDescriptor {
    12→  return {
    13→    id: `${workspaceId}:pages`,
    14→    descriptorId: "virtual-folder",
    15→    label: i18n.t("page.pages", "Pages"),
    16→    href: `/workspace/${encodeURIComponent(workspaceId)}/pages`,
    17→    icon: { type: "lucide", value: "layout-grid" },
    18→    meta: { workspaceId },
    19→  };
    20→}
    21→
    22→function createWorkspaceRootDescriptor(
    23→  workspaceId: string
    24→): BreadcrumbNodeDescriptor {
    25→  return {
    26→    id: `workspace:${workspaceId}`,
    27→    descriptorId: "workspace",
    28→    label: workspaceId,
    29→    href: `/workspace/${encodeURIComponent(workspaceId)}`,
    30→    meta: { workspaceId },
    31→  };
    32→}
    33→
    34→function resolveWorkspacePage(
    35→  pages: PageConfig[] | undefined,
    36→  pageOrSlug: PageConfig | string
    37→): PageConfig {
    38→  if (typeof pageOrSlug !== "string") {
    39→    return pageOrSlug;
    40→  }
    41→
    42→  return pages?.find((item) => item.slug === pageOrSlug) ?? {
    43→    slug: pageOrSlug,
    44→    name: pageOrSlug.split("/").filter(Boolean).pop() ?? pageOrSlug,
    45→    permission: ["read"],
    46→    path: pageOrSlug,
    47→    type: "markdown",
    48→  };
    49→}
    50→
    51→function buildWorkspacePagePathDescriptors(
    52→  workspaceId: string,
    53→  pages: PageConfig[] | undefined,
    54→  page: PageConfig
    55→): BreadcrumbNodeDescriptor[] {
    56→  const segments = page.slug.split("/").filter(Boolean);
    57→
    58→  return segments.map((segment, index) => {
    59→    const slugAtDepth = segments.slice(0, index + 1).join("/");
    60→    const isLeaf = index === segments.length - 1;
    61→    const matchedPage = isLeaf
    62→      ? page
    63→      : pages?.find((item) => item.slug === slugAtDepth);
    64→
    65→    return {
    66→      id: `${workspaceId}:page:${slugAtDepth}`,
    67→      descriptorId: "workspace-page",
    68→      label: matchedPage?.name ?? segment,
    69→      href: `/workspace/${encodeURIComponent(workspaceId)}/pages/${slugAtDepth}`,
    70→      icon: matchedPage?.icon,
    71→      meta: {
    72→        workspaceId,
    73→        pageSlug: slugAtDepth,
    74→      },
    75→    };
    76→  });
    77→}
    78→
    79→function buildWorkspacePageTreeDescriptors(
    80→  workspaceId: string,
    81→  path: PageTreeNode[]
    82→): BreadcrumbNodeDescriptor[] {
    83→  return path.map((item) => ({
    84→    id: `${workspaceId}:page:${item.page.slug}`,
    85→    descriptorId: "workspace-page",
    86→    label: item.page.name,
    87→    href: `/workspace/${encodeURIComponent(workspaceId)}/pages/${item.page.slug}`,
    88→    icon: item.page.icon,
    89→    meta: {
    90→      workspaceId,
    91→      pageSlug: item.page.slug,
    92→    },
    93→  }));
    94→}
    95→
    96→export function resolveWorkspacePageNavigationState(
    97→  workspaceId: string,
    98→  pages: PageConfig[] | undefined,
    99→  pageOrSlug: PageConfig | string
   100→){
   101→  const page = resolveWorkspacePage(pages, pageOrSlug);
   102→
   103→  return resolveNavigationState(page, [
   104→    createWorkspaceRootDescriptor(workspaceId),
   105→    createWorkspacePagesIndexDescriptor(workspaceId),
   106→    ...buildWorkspacePagePathDescriptors(workspaceId, pages, page),
   107→  ]);
   108→}
   109→
   110→export function resolveWorkspacePageTreeNavigationState(
   111→  workspaceId: string,
   112→  ancestors: PageTreeNode[],
   113→  node: PageTreeNode
   114→){
   115→  const path = [...ancestors, node];
   116→
   117→  return resolveNavigationState(node.page, [
   118→    createWorkspaceRootDescriptor(workspaceId),
   119→    createWorkspacePagesIndexDescriptor(workspaceId),
   120→    ...buildWorkspacePageTreeDescriptors(workspaceId, path),
   121→  ]);
   122→}
