    37→
    38→function getTabIconData(tab: TabViewModel): IconData {
    39→  if (tab.icon) {
    40→    return tab.icon;
    41→  }
    42→  return getDescriptorIcon(tab.descriptorId) ?? { type: "lucide", value: "file-text" };
    43→}
    44→
    45→export interface SortableTabItemProps {
    46→  tab: TabViewModel;
    47→  isActive: boolean;
    48→  isOnlyTab?: boolean;
    49→  /** Whether this is a newly created tab (for entrance animation) */
    50→  isNew?: boolean;
    51→  isDragging?: boolean;
    52→  onSelect: () => void;
    53→  onClose: () => void;
    54→  onPin: () => void;
    55→  onUnpin: () => void;
    56→  onCloseOthers: () => void;
    57→  onCloseRight: () => void;
    58→  onDuplicate: () => void;
    59→  onReopenClosed: () => void;
