    68→
    69→export function SortableTabItem({
    70→  tab,
    71→  isActive,
    72→  isOnlyTab = false,
    73→  isDragging = false,
    74→  isNew = false,
    75→  onSelect,
    76→  onClose,
    77→  onPin,
    78→  onUnpin,
    79→  onCloseOthers,
    80→  onCloseRight,
    81→  onDuplicate,
    82→  onReopenClosed,
    83→  onCopyLink,
    84→  onDetach,
    85→  onMoveToStart,
    86→  onMoveToEnd,
    87→  canReopenClosed = false,
    88→  canMoveToStart = false,
    89→  canMoveToEnd = false,
    90→}: SortableTabItemProps) {
    91→  const { t } = useTranslation();
    92→  const {
    93→    attributes,
    94→    listeners,
    95→    setNodeRef,
    96→    transform,
    97→    transition,
    98→    isDragging: isSortableDragging,
    99→  } = useSortable({ id: tab.id });
   100→
   101→  const iconData = getTabIconData(tab);
