   156→      <div
   157→        ref={setNodeRef}
   158→        style={{
   159→          ...style,
   160→          opacity: isAnimating ? 0 : 1,
   161→          transform: isAnimating
   162→            ? "translateX(20px) scale(0.8)"
   163→            : CSS.Transform.toString(transform),
   164→        }}
   165→        className="transition-all duration-300 ease-out"
   166→        {...attributes}
   167→        {...listeners}
   168→        onMouseEnter={() => setIsHovered(true)}
   169→        onMouseLeave={() => setIsHovered(false)}
   170→      >
   171→        <ContextMenu>
   172→          <Tooltip>
