   174→              <ContextMenuTrigger asChild>
   175→                <button
   176→                  onClick={handleClick}
   177→                  onMouseDown={handleMiddleClick}
   178→                  className={cn(
   179→                    "relative h-7 w-7 flex items-center justify-center rounded-md",
   180→                    "text-muted-foreground transition-all duration-200",
   181→                    "hover:bg-accent hover:text-accent-foreground",
   182→                    "cursor-grab active:cursor-grabbing",
   183→                    isActive && [
   184→                      "bg-background text-foreground",
   185→                      "shadow-sm ring-1 ring-border/50",
   186→                    ],
