   191→                  {isHovered || dragging ? (
   192→                    <GripVertical className="h-3.5 w-3.5 text-muted-foreground/60" />
   193→                  ) : (
   194→                    <IconDisplay icon={iconData} size="sm" />
   195→                  )}
   196→                  {isActive && (
   197→                    <span className="absolute bottom-0 left-1/2 -translate-x-1/2 w-3 h-0.5 bg-primary rounded-full" />
   198→                  )}
   199→                </button>
   200→              </ContextMenuTrigger>
   201→            </TooltipTrigger>
   202→            <TooltipContent side="bottom" className="text-xs">
   203→              {tab.titleKey ? t(tab.titleKey, tab.label) : tab.label}
   204→            </TooltipContent>
   205→          </Tooltip>
   206→          <ContextMenuContent className="w-48">
   207→            <ContextMenuItem onClick={onClose}>
   208→              <X className="h-4 w-4 mr-2" />
   209→              {t("common.close")}
   210→            </ContextMenuItem>
   211→            <ContextMenuItem onClick={onCloseOthers}>
   212→              {t("tabBar.closeOthers", "Close Others")}
   213→            </ContextMenuItem>
   214→            <ContextMenuItem onClick={onCloseRight}>
   215→              {t("tabBar.closeToRight", "Close Tabs to the Right")}
   216→            </ContextMenuItem>
   217→            <ContextMenuSeparator />
   218→            <ContextMenuItem onClick={onReopenClosed} disabled={!canReopenClosed}>
   219→              {t("tabBar.reopenClosedTab", "Reopen Closed Tab")}
   220→            </ContextMenuItem>
   221→            <ContextMenuItem onClick={onDuplicate}>
   222→              {t("tabBar.duplicateTab", "Duplicate Tab")}
   223→            </ContextMenuItem>
   224→            <ContextMenuItem onClick={onDetach}>
   225→              <ExternalLink className="h-4 w-4 mr-2" />
   226→              {t("tabBar.detachToNewWindow", "Detach to New Window")}
   227→            </ContextMenuItem>
   228→            <ContextMenuSeparator />
   229→            <ContextMenuItem onClick={onUnpin}>
   230→              <PinOff className="h-4 w-4 mr-2" />
   231→              {t("tabBar.unpinTab", "Unpin Tab")}
