     4→// ─── Atomic Stack Operations ─────────────────────────────────────────────────
     5→
     6→export function getStackTop(
     7→  stack: BreadcrumbStackItem[]
     8→): BreadcrumbStackItem | undefined {
     9→  return stack[stack.length - 1];
    10→}
    11→
    12→export function pushStackItem(
    13→  stack: BreadcrumbStackItem[],
    14→  item: BreadcrumbStackItem
    15→): BreadcrumbStackItem[] {
    16→  return [...stack, item];
    17→}
    18→
    19→export function replaceStackTop(
    20→  stack: BreadcrumbStackItem[],
    21→  item: BreadcrumbStackItem
    22→): BreadcrumbStackItem[] {
    23→  if (stack.length === 0) {
    24→    return [item];
    25→  }
    26→
    27→  return [...stack.slice(0, -1), item];
    28→}
    29→
    30→export function popTo(
    31→  stack: BreadcrumbStackItem[],
    32→  index: number
    33→): BreadcrumbStackItem[] {
    34→  if (stack.length === 0) {
    35→    return stack;
    36→  }
    37→
    38→  const normalizedIndex = Math.max(0, Math.min(index, stack.length - 1));
    39→  return stack.slice(0, normalizedIndex + 1);
    40→}
    41→
    42→// ─── Item Factory ────────────────────────────────────────────────────────────
    43→
    44→export function createBreadcrumbItem(
    45→  item: BreadcrumbStackItem
    46→): BreadcrumbStackItem {
    47→  return {
    48→    ...item,
    49→    icon: item.icon ?? getDescriptorIcon(item.descriptorId),
    50→  };
    51→}
